import sys

def diagonal(index):
    # Entries are C(index-k, k), from bottom left to top right.
    value = 1
    for k in range(index // 2 + 1):
        yield value
        if 2 * (k + 1) <= index:
            value = (value * (index - 2 * k) * (index - 2 * k - 1)
                     // ((k + 1) * (index - k)))

target = int(sys.stdin.read())
a = b = 1
index = 0
while a < target:
    a, b = b, a + b
    index += 1

frequencies = {}
for n in range(index + 1):
    for value in diagonal(n):
        # Only zero, one, or at least two occurrences matter.
        frequencies[value] = min(2, frequencies.get(value, 0) + 1)
print(sum(count == 1 for count in frequencies.values()))
